<?php get_header();the_post();$id=get_the_ID();?><article class="gmr-wrap gmr-single-story"><header class="gmr-single-story__head"><span class="gmr-kicker"><?php echo esc_html(gmr_theme_event_types($id)?:'Agenda');?></span><h1><?php the_title();?></h1><?php if(has_excerpt()):?><p><?php echo esc_html(get_the_excerpt());?></p><?php endif;?></header><?php the_post_thumbnail('full',array('class'=>'gmr-single-story__cover'));?><div class="gmr-event-facts"><div><span>Fecha</span><?php echo esc_html(gmr_theme_event_date($id));?></div><div><span>Lugar</span><?php echo esc_html(get_post_meta($id,'gmr_event_venue',true));?></div><div><span>Modalidad</span><?php echo esc_html(ucfirst(get_post_meta($id,'gmr_event_modality',true)));?></div></div><div class="gmr-single-story__content"><?php the_content();$register=get_post_meta($id,'gmr_event_registration',true);if($register):?><p><a class="gmr-button" href="<?php echo esc_url($register);?>">Registrarse</a></p><?php endif;?></div></article><?php get_footer();?>
